package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

func getCandiesEaten(n, k int) int {
	if n == 1 {
		return 0
	}
	n--
	candies := 1
	sum := 2
	consumed := 0
	for n > 0 {
		for candies <= k {
			candies += sum
			sum++
			n--
		}
		candiesToSubtract := candies - k
		n -= candiesToSubtract
		consumed += candiesToSubtract
		candies -= candiesToSubtract
	}
	return consumed
}

func main() {
	data, _ := os.ReadAll(os.Stdin)
	fields := strings.Fields(string(data))
	if len(fields) < 2 {
		return
	}
	n, _ := strconv.Atoi(fields[0])
	k, _ := strconv.Atoi(fields[1])
	fmt.Println(getCandiesEaten(n, k))
}

